var e={klipperscreenStudio:{intro:{t:0,b:{t:2,i:[{t:3}],s:`プリンターの KlipperScreen タッチスクリーン設定を安全に編集し、KlipperScreen を再起動して適用します。保存のたびに、まずバックアップが作成されます。`}},selector:{title:{t:0,b:{t:2,i:[{t:3}],s:`タッチスクリーン`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`プリンターのディスプレイで動作するインターフェースを選択します。`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`更新`}},active:{t:0,b:{t:2,i:[{t:3}],s:`動作中`}},boot:{t:0,b:{t:2,i:[{t:3}],s:`起動時`}},notInstalled:{t:0,b:{t:2,i:[{t:3}],s:`未インストール`}},use:{t:0,b:{t:2,i:[{t:3}],s:`使用する`}},switching:{t:0,b:{t:2,i:[{t:3}],s:`切り替え中…`}},persist:{t:0,b:{t:2,i:[{t:3}],s:`起動時の既定としても設定する`}},installedNotManageable:{t:0,b:{t:2,i:[{t:3}],s:`インストール済み`}},notManageableHint:{t:0,b:{t:2,i:[{t:3}],s:`インストール済みですが、ここからは切り替えできません (systemd サービスなし)。`}}},touchPanel:{title:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind コントロール`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind のチェックとテストを画面から直接実行できます。`}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`ヘルプ`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen Studio について`}},close:{t:0,b:{t:2,i:[{t:3}],s:`閉じる`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`読み方`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`下の設定テキストを編集します（そのままでも構いません）。`}},{t:0,b:{t:2,i:[{t:3}],s:`保存 - 現在のファイルがまずバックアップされ、プリンターが動作中の場合は保存が拒否されます。`}},{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen を再起動して、物理画面に変更を適用します。`}},{t:0,b:{t:2,i:[{t:3}],s:`行末は UNIX (LF) で、保存時に自動で適用されます。`}}],topics:{glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`用語集`}},body:{t:0,b:{t:2,i:[{t:3}],s:`ここで使われている KlipperScreen 用語の簡単な定義です。`}}},config:{title:{t:0,b:{t:2,i:[{t:3}],s:`Config タブとは？`}},body:{t:0,b:{t:2,i:[{t:3}],s:`生の KlipperScreen.conf です。任意の設定を手で編集できます。保存時にまずファイルをバックアップし、プリンターが動作中なら拒否され、読み込んでから画面側でファイルが変更されていれば警告します。多くの人は代わりに 設定 / メニュー / テーマ タブを使います。`}}},settings:{title:{t:0,b:{t:2,i:[{t:3}],s:`設定タブとは？`}},body:{t:0,b:{t:2,i:[{t:3}],s:`最もよく使う [main] オプションをフォームにしたものです - テーマ、言語、画面スリープ、フォントサイズ、各種トグル。ライブ設定から事前入力され、変更したオプションだけが書き込まれます。再起動して適用します。`}}},menus:{title:{t:0,b:{t:2,i:[{t:3}],s:`メニュータブとは？`}},body:{t:0,b:{t:2,i:[{t:3}],s:`タッチスクリーンのボタングリッドを設計します。各ツリー（__main がホームグリッド、__print が印刷画面）にボタンが並びます。追加・名称変更・並べ替え・入れ子ができ、それぞれをサブメニューを開く、組み込み画面を開く、G-code を実行するに設定できます。`}}},themes:{title:{t:0,b:{t:2,i:[{t:3}],s:`テーマタブとは？`}},body:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen テーマを作成します。パレットトークンごとに色と角丸を選び、ライブプレビューを見ながら作成して画面に適用します。プレビューはあくまで目安です - 実際の画面は GTK で描画されます。`}}},kiosk:{title:{t:0,b:{t:2,i:[{t:3}],s:`キオスクタブとは？`}},body:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind Flow 自体を全画面ブラウザとしてタッチスクリーンに表示します - 画面に表示する内容を完全に制御できます。KlipperScreen との切り替えは元に戻せます（既定では一時的で、再起動すると KlipperScreen に戻ります）。プリンターホストで一度だけインストーラーの実行が必要です。`}}}},glossary:{klipperScreen:{term:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen`}},def:{t:0,b:{t:2,i:[{t:3}],s:`プリンターに取り付けた小型ディスプレイで動作するタッチスクリーン UI です - この Web パネルとは別物です。`}}},theme:{term:{t:0,b:{t:2,i:[{t:3}],s:`テーマ`}},def:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen の外観 - 色、アイコン、角丸です。ホスト上の styles/<name> フォルダーに置かれ、見た目だけです（レイアウトは変更できません）。`}}},menu:{term:{t:0,b:{t:2,i:[{t:3}],s:`メニュー (__main / __print)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen が表示するボタンのグリッドです。__main がホーム画面、__print が印刷中に表示される画面、__splashscreen が起動画面です。`}}},panel:{term:{t:0,b:{t:2,i:[{t:3}],s:`パネル`}},def:{t:0,b:{t:2,i:[{t:3}],s:`ボタンから開ける組み込みの KlipperScreen 画面です（移動、温度、押し出し、ベッドメッシュなど）。その内部の内容は KlipperScreen により固定されています。`}}},autoBlock:{term:{t:0,b:{t:2,i:[{t:3}],s:`自動生成ブロック (#~#)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen が conf 末尾の #~# マーカー以降に自身のために書き込むセクションです。FilaMind はこれを編集せず - その上にあるあなたの設定だけを扱います。`}}},kiosk:{term:{t:0,b:{t:2,i:[{t:3}],s:`キオスク`}},def:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen の代わりにタッチスクリーンで全画面ブラウザを実行し、画面に FilaMind Flow を表示します。完全に元に戻せます。`}}}}},status:{checking:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen を確認中…`}},absent:{t:0,b:{t:2,i:[{t:3}],s:`このプリンターで KlipperScreen が検出されませんでした（KlipperScreen.conf がなく、Moonraker からも報告されません）。このツールを使うには KlipperScreen をインストールしてください。`}},present:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen を検出しました`}},theme:{t:0,b:{t:2,i:[{t:3}],s:`テーマ`}},language:{t:0,b:{t:2,i:[{t:3}],s:`言語`}},notRestartable:{t:0,b:{t:2,i:[{t:3}],s:`Moonraker は KlipperScreen を自動で再起動できません - 保存後に手動で再起動してください。`}}},editor:{loading:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen.conf を読み込み中…`}},reload:{t:0,b:{t:2,i:[{t:3}],s:`再読み込み`}},save:{t:0,b:{t:2,i:[{t:3}],s:`設定を保存`}},saving:{t:0,b:{t:2,i:[{t:3}],s:`保存中…`}},saved:{t:0,b:{t:2,i:[{t:3}],s:`保存しました（バックアップ済み）`}},unsaved:{t:0,b:{t:2,i:[{t:3}],s:`未保存の変更`}}},save:{busy:{t:0,b:{t:2,i:[{t:3}],s:`プリンターが動作中のため拒否されました - アイドル状態になってから再試行してください。`}},stale:{t:0,b:{t:2,i:[{t:3}],s:`読み込んでから KlipperScreen.conf がディスク上で変更されました（おそらく画面側で編集されました）。その変更を上書きしないよう、保存前に再読み込みしてください。`}}},view:{config:{t:0,b:{t:2,i:[{t:3}],s:`設定`}},settings:{t:0,b:{t:2,i:[{t:3}],s:`設定`}},menus:{t:0,b:{t:2,i:[{t:3}],s:`メニュー`}},themes:{t:0,b:{t:2,i:[{t:3}],s:`テーマ`}},kiosk:{t:0,b:{t:2,i:[{t:3}],s:`キオスク`}},fmscreen:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind 画面`}}},settings:{loading:{t:0,b:{t:2,i:[{t:3}],s:`設定を読み込み中…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`最もよく使う KlipperScreen の表示オプションをフォームにしたものです。変更したオプションだけが書き込まれ - それ以外は現在の値が維持されます。再起動して適用します。`}},onlyChanged:{t:0,b:{t:2,i:[{t:3}],s:`ここで変更した設定だけが KlipperScreen.conf に書き込まれます。`}},save:{t:0,b:{t:2,i:[{t:3}],s:`設定を保存`}},savedRestart:{t:0,b:{t:2,i:[{t:3}],s:`保存しました - KlipperScreen を再起動して適用してください。`}},unset:{t:0,b:{t:2,i:[{t:3}],s:`未設定のまま（既定）`}},never:{t:0,b:{t:2,i:[{t:3}],s:`なし（常にオン）`}},fontSize:{small:{t:0,b:{t:2,i:[{t:3}],s:`小`}},medium:{t:0,b:{t:2,i:[{t:3}],s:`中`}},large:{t:0,b:{t:2,i:[{t:3}],s:`大`}},max:{t:0,b:{t:2,i:[{t:3}],s:`最大`}}},label:{theme:{t:0,b:{t:2,i:[{t:3}],s:`テーマ`}},language:{t:0,b:{t:2,i:[{t:3}],s:`言語`}},screen_blanking:{t:0,b:{t:2,i:[{t:3}],s:`画面スリープまでの時間`}},font_size:{t:0,b:{t:2,i:[{t:3}],s:`フォントサイズ`}},"24htime":{t:0,b:{t:2,i:[{t:3}],s:`24時間表示`}},use_dpms:{t:0,b:{t:2,i:[{t:3}],s:`DPMS で画面をブランクする`}},show_cursor:{t:0,b:{t:2,i:[{t:3}],s:`マウスカーソルを表示`}},confirm_estop:{t:0,b:{t:2,i:[{t:3}],s:`緊急停止の前に確認`}},show_heater_power:{t:0,b:{t:2,i:[{t:3}],s:`ヒーター出力 % を表示`}},autoclose_popups:{t:0,b:{t:2,i:[{t:3}],s:`ポップアップを自動で閉じる`}}}},kiosk:{loading:{t:0,b:{t:2,i:[{t:3}],s:`画面を確認中…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind Flow 自体を全画面ブラウザとしてタッチスクリーンに表示します - 画面に表示する内容を完全に制御できます。KlipperScreen と切り替わり、一方を起動するともう一方が停止します。`}},current:{t:0,b:{t:2,i:[{t:3}],s:`現在の画面`}},mode:{kiosk:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind キオスク`}},klipperscreen:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen`}},none:{t:0,b:{t:2,i:[{t:3}],s:`どちらも未起動`}}},notInstalled:{t:0,b:{t:2,i:[{t:3}],s:`キオスクはまだ未インストールです`}},setupHint:{t:0,b:{t:2,i:[{t:3}],s:`プリンターホストで一度だけ実行してください（全画面ブラウザ + キオスクサービスをインストールします）：`}},persist:{t:0,b:{t:2,i:[{t:3}],s:`起動時の既定にする（そうしないと切り替えは一時的で、再起動すると元に戻ります）。`}},safety:{t:0,b:{t:2,i:[{t:3}],s:`既定では一時的です。再起動するともう一方が戻ります。万一画面が暗くなったら、SSH で次を実行してください： sudo systemctl start KlipperScreen`}},switchBtn:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind に切り替え`}},restoreBtn:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen を復元`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`更新`}},confirmSwitchTitle:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind を画面に表示しますか？`}},confirmRestoreTitle:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen を復元しますか？`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`一方の画面サービスを停止し、もう一方を起動します。実行中の印刷には影響しませんが、切り替え中はタッチスクリーンが数秒間真っ暗になります。`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`実行する`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`キャンセル`}},switchedNote:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind が画面を引き継いでいます - 数秒で表示されるはずです。`}},restoredNote:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen が戻ってきています - まもなく画面が復帰するはずです。`}}},menus:{loading:{t:0,b:{t:2,i:[{t:3}],s:`メニューを読み込み中…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`タッチスクリーンに表示する内容を設計します。各メニューのボタン、その順序、それぞれの動作を設定できます。ホーム画面のグリッドが __main ツリー、印刷画面が __print です。`}},addItem:{t:0,b:{t:2,i:[{t:3}],s:`ボタンを追加`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`まだ項目がありません - 追加してください。`}},up:{t:0,b:{t:2,i:[{t:3}],s:`上へ移動`}},down:{t:0,b:{t:2,i:[{t:3}],s:`下へ移動`}},addChild:{t:0,b:{t:2,i:[{t:3}],s:`サブ項目を追加`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`削除`}},name:{t:0,b:{t:2,i:[{t:3}],s:`名前`}},icon:{t:0,b:{t:2,i:[{t:3}],s:`アイコン`}},action:{t:0,b:{t:2,i:[{t:3}],s:`アクション`}},actSubmenu:{t:0,b:{t:2,i:[{t:3}],s:`サブメニューを開く`}},actPanel:{t:0,b:{t:2,i:[{t:3}],s:`画面を開く`}},actGcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code を実行`}},panel:{t:0,b:{t:2,i:[{t:3}],s:`画面`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},enable:{t:0,b:{t:2,i:[{t:3}],s:`表示条件`}},save:{t:0,b:{t:2,i:[{t:3}],s:`メニューを保存`}},newItem:{t:0,b:{t:2,i:[{t:3}],s:`新規ボタン`}},savedRestart:{t:0,b:{t:2,i:[{t:3}],s:`メニューを保存しました - KlipperScreen を再起動すると表示されます。`}}},themes:{loading:{t:0,b:{t:2,i:[{t:3}],s:`テーマを読み込み中…`}},palette:{t:0,b:{t:2,i:[{t:3}],s:`パレット`}},radius:{t:0,b:{t:2,i:[{t:3}],s:`角丸`}},preview:{t:0,b:{t:2,i:[{t:3}],s:`ライブプレビュー`}},btn:{t:0,b:{t:2,i:[{t:3}],s:`ボタン`}},previewWarn:{t:0,b:{t:2,i:[{t:3}],s:`警告`}},previewApprox:{t:0,b:{t:2,i:[{t:3}],s:`おおよそのプレビューです - 実際の画面は GTK で描画されるため、わずかな違いが生じます。`}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`新しいテーマ名`}},createApply:{t:0,b:{t:2,i:[{t:3}],s:`作成して適用`}},createOnly:{t:0,b:{t:2,i:[{t:3}],s:`作成のみ`}},installed:{t:0,b:{t:2,i:[{t:3}],s:`インストール済みのテーマ`}},apply:{t:0,b:{t:2,i:[{t:3}],s:`適用`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`テーマを削除`}},generated:{t:0,b:{t:2,i:[{t:3}],s:`ここで作成`}},created:{t:0,b:{t:2,i:[{t:3}],s:`テーマを作成しました。リストから適用し、再起動してください。`}},appliedRestart:{t:0,b:{t:2,i:[{t:3}],s:`テーマを設定しました - KlipperScreen を再起動すると表示されます。`}},previewTitle:{t:0,b:{t:2,i:[{t:3}],s:`プリンター`}}},restart:{button:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen を再起動`}},restarting:{t:0,b:{t:2,i:[{t:3}],s:`再起動中…`}},done:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen を再起動しています - まもなく画面が再読み込みされます。`}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen を再起動しますか？`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`変更を適用するためにタッチスクリーンサービスを再起動します。実行中の印刷には影響しませんが、画面が数秒間真っ暗になります。`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`再起動`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`キャンセル`}}}}};export{e as default};